    '  }',
    '}',
    'void wgpuTessRun() {',
    '  wgpuTessP = 0; wgpuTessPrims = 0; wgpuRingPrepare(4);',
    '  int n0 = wgpuTessNi[0], n1 = wgpuTessNi[1];',
    '  if (n0 == 1 && n1 == 1) {',
    '    int a = wgpuTessAdd(vec3(0.0, 0.0, 0.0)), b = wgpuTessAdd(vec3(1.0, 0.0, 0.0)), c = wgpuTessAdd(vec3(1.0, 1.0, 0.0)), d = wgpuTessAdd(vec3(0.0, 1.0, 0.0));',
    '    wgpuTessTriangle(a, b, c); wgpuTessTriangle(a, c, d); return;',
