    '  float ua = 0.0, va = 0.0;',
    '  wgpuQuadRing(0, ua, va);',
    '  for (int k = 0; k < 40; k++) {',
    '    int m0 = n0 - 2 * k, m1 = n1 - 2 * k, i0 = m0 - 2, i1 = m1 - 2;',
