      reads.push('  for (int wgpuI = 0; wgpuI < '+control.vertices+'; wgpuI++) {','    uint wgpuV = wgpuControlBase + uint(wgpuI) * '+control.vertexSlots+'u;');
      reads=reads.concat(wgpuTessCopy(input,function(n){return 'wgpuTessControl[wgpuV + '+(from.slot+n)+'u]';},'wgpuI',true).lines);
